# -*- coding: utf-8 -*-
import sys, html
sys.path.insert(0,"scripts"); from inventory import INV
NAMES={"CONFIRM":"устояло","WEAK":"ослаблено","DISSOLVE":"растворилось","ATTRIB":"отнесено","RETRACT":"отозвано"}
COL={"CONFIRM":"#3fb950","WEAK":"#d29922","DISSOLVE":"#f85149","ATTRIB":"#a371f7","RETRACT":"#f85149"}
GRP=[("A","Словарь и устройство слова"),("G","Память в порождении"),("B","Последовательность и порядок"),
     ("C","Позиция в строке"),("D","Деления рукописи"),("E","Целое: энтропия, Ципф, объём"),
     ("F","Гипотезы о происхождении")]
import collections
V=collections.Counter(d["verdict"] for d in INV)
not_survive=V["DISSOLVE"]+V["WEAK"]+V["ATTRIB"]+V["RETRACT"]
out=[]
out.append('  <h2>Инвентарь: сколько заявленных особенностей переживает собственный контроль</h2>')
out.append('  <p class="sub">Скелет будущей статьи. Пятьдесят восемь утверждений, по каждому — чьё оно, какой контроль применён и что осталось</p>')
out.append('  <div class="col"><p>Разбор дошёл до точки, где полезнее не добавлять находки, а свести счёт. Ниже — все содержательные утверждения о рукописи, которые я проверял: и чужие, и свои. Колонка «чьё» существует потому, что за эту сессию я шесть раз объявлял находкой то, что было известно; колонка «контроль» — потому что почти каждое утверждение держится или падает на выборе нулевой модели, а не на данных.</p></div>')
out.append(f'''  <div class="pull"><p>Из пятидесяти восьми утверждений <strong>{V["CONFIRM"]} устояло</strong>, а {not_survive} в заявленном виде не выжили: {V["DISSOLVE"]} растворились под контролем, {V["WEAK"]} ослаблены до величины, которая ничего не решает, {V["ATTRIB"]} оказались следствием другого явления, {V["RETRACT"]} я отозвал. <strong>Шестьдесят девять процентов инвентаря — не факты о рукописи, а факты о том, с чем её сравнивали.</strong></p></div>''')
out.append('  <p>Из пятидесяти восьми записей своими я заявляю двадцать восемь; остальные тридцать — проверка чужих утверждений, и в большинстве случаев проверка их подтверждает, но меняет формулировку.</p>')
for g,title in GRP:
    rows=[d for d in INV if d["id"].startswith(g)]
    out.append(f'  <h3>{html.escape(title)}</h3>')
    out.append('  <div class="tbl-scroll"><table><thead><tr><th>Утверждение</th><th>Чьё</th><th>Контроль</th><th>Итог</th></tr></thead><tbody>')
    for d in rows:
        c=COL[d["verdict"]]; v=NAMES[d["verdict"]]
        out.append(f'    <tr><td class="k"><strong>{html.escape(d["claim"])}</strong><br>'
                   f'<span style="color:var(--ink-3);font-size:13px">{html.escape(d["nums"])}</span></td>'
                   f'<td class="num" style="font-size:13px">{html.escape(d["whose"])}</td>'
                   f'<td class="num" style="font-size:13px">{html.escape(d["control"])}</td>'
                   f'<td class="num"><span style="color:{c};font-weight:600">{v}</span></td></tr>')
    out.append('  </tbody></table></div>')
out.append('''  <h3>Куда распределилось то, что устояло</h3>
  <p>Второй результат инвентаря — не счёт, а адресация. Прежнее разбиение на три слоя держалось на разложении, которое отозвано. Ниже — то, что осталось после правки.</p>
  <div class="tbl-scroll"><table><thead><tr><th>Слой</th><th>Что туда попало</th><th>Что это значит</th></tr></thead><tbody>
    <tr><td class="k"><strong>Единица измерения</strong></td><td class="num">низкая условная энтропия; жёсткость слотов</td><td class="num">на типах разрыв с латынью ВДВОЕ меньше, чем на токенах (2,43× против 4,52×; 0,88× против 0,75×)</td></tr>
    <tr><td class="k"><strong>Необъяснённое</strong></td><td class="num">отсутствие запрета на одинаковых соседей; недостаток стыка по трём знакам; остаток плотности 1,26× сверх марковской модели</td><td class="num">плотность УШЛА отсюда почти целиком: цепь 2-го порядка по знакам даёт 80 % её и форму почти точно</td></tr>
    <tr><td class="k"><strong>Отозвано своё</strong><br>6 записей</td><td class="num">разложимость выше языков; наслаивание; атрибуция плотности; атрибуция стыка; уникальность порядка слов; длина подписей</td><td class="num">четыре из шести умерли одинаково: набор сравнения или критерий отбора не был независим от объясняемой величины</td></tr>
  </tbody></table></div>
  <p style="color:var(--ink-3);font-size:15px">Практический вывод для всякого следующего предложения о рукописи: прежде чем объяснять аномалию, надо проверить, не снимается ли она вместе с аффиксным слоем и не является ли она пересказом частотного распределения. Из четырёх знаменитых странностей — низкая энтропия, жёсткая слотовость, соседние повторы, устройство стыка — <strong>три первые оказались именно такими</strong>, и объяснять требуется гораздо меньше, чем принято считать.</p>
''')
open("/tmp/inv_block.html","w",encoding="utf-8").write("\n".join(out)+"\n")
print("собрано", len("\n".join(out)), "знаков;", f"устояло {V['CONFIRM']}, не выжило {not_survive}")
